import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o}from"./chunks/EN.P9aPnFBv.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as s}from"./chunks/OFF.BrU7kQE-.js";import{_ as i}from"./chunks/M-S-SY8d2.DVL3poO_.js";import{_ as n,o as r,c as l,a3 as c}from"./chunks/framework.g9mfNVRQ.js";const _=JSON.parse('{"title":"xDrip Sync","description":"","frontmatter":{},"headers":[],"relativePath":"use/sync.md","filePath":"use/sync.md"}'),p={name:"use/sync.md"};function d(m,t,h,u,y,b){return r(),l("div",null,[...t[0]||(t[0]=[c('<div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> xDrip sync</p></div><div class="warning custom-block"><p class="custom-block-title">Old xDrip Sync</p><p>In July 2024, Google shut down the deprecated <a href="https://firebase.google.com/docs/cloud-messaging/migrate-v1" target="_blank" rel="noreferrer">Firebase API</a> xDrip used for xDrip Sync.<br> Update xDrip to a version from <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.07.23" target="_blank" rel="noreferrer">July 23rd 2024</a> to use the legacy Sync method.<br> Updating xDrip to the latest release is recommended.</p></div><div class="warning custom-block"><p class="custom-block-title">Warning</p><p><a href="https://play.google.com/store/apps/details?id=com.google.android.gms" target="_blank" rel="noreferrer">Google Play services</a> are mandatory to use this feature. Make sure they are present, enabled and not subject to battery optimization.</p></div><p>xDrip provides a unique real time sync mechanism between Android devices making BG and treatments sharing the easiest possible task.</p><p>The underlying security key can be customized instead of using the Google account key (not editable).</p><div class="admonition xdripitem"><p class="admonition-title">Sync using custom security key <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Key is used instead of Google account</p></div><h5 id="handset-group-security-sync-key" tabindex="-1">Handset group security sync key <a class="header-anchor" href="#handset-group-security-sync-key" aria-label="Permalink to &quot;Handset group security sync key&quot;">​</a></h5><p>A unique key is created at xDrip install (it will be different if you reinstall xDrip) and should match all devices using xDrip sync. Even if you can customize this key making it your own (letters and numbers) you will usually leave it as generated.</p><div class="admonition xdripitem"><p class="admonition-title">Handset Group Security Sync Key</p><p> Handset sync grouping key</p></div><h5 id="be-master-for-followers" tabindex="-1">Be master for followers <a class="header-anchor" href="#be-master-for-followers" aria-label="Permalink to &quot;Be master for followers&quot;">​</a></h5><p>The device getting BG data from the sensor will be Master, all others will be Followers.<br> Only one master can use the same security key. If two masters are detected, the newly arrived one will be disabled and return to follower state.</p><div class="admonition xdripitem"><p class="admonition-title">Be master for followers <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> This device will send data to followers</p></div><h5 id="accept-followers-actions" tabindex="-1">Accept follower actions <a class="header-anchor" href="#accept-followers-actions" aria-label="Permalink to &quot;Accept follower actions {#accept-followers-actions}&quot;">​</a></h5><p>You can set up the master phone to receive and accept followers&#39; treatments and calibrations. Be extremely careful when using this feature if you use automatic calibrations. Also remember sensor start and stop might be sent by followers and accepted by the master.</p><div class="admonition xdripitem"><p class="admonition-title">Accept follower actions <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Treatments, Calibrations and other actions from followers will be accepted</p></div><h5 id="use-xdrip-cloud" tabindex="-1">Use xDrip Cloud <a class="header-anchor" href="#use-xdrip-cloud" aria-label="Permalink to &quot;Use xDrip Cloud&quot;">​</a></h5><p>After Google shut down the deprecated <a href="https://firebase.google.com/docs/cloud-messaging/migrate-v1" target="_blank" rel="noreferrer">Firebase API</a> used for xDrip Sync in July 2024, a new sharing method has been developed.</p><div class="warning custom-block"><p class="custom-block-title">Must be set identically on all phones</p><p>Master and followers. Either it is ON for all, or OFF for all.</p></div><div class="admonition xdripitem"><p class="admonition-title">Use xDrip Cloud <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Use the new xDrip cloud servers. Master and followers must all have this setting set the same.</p></div><p>If xDrip uses too much battery when on SIM data you can try to enable this.</p><div class="admonition xdripitem"><p class="admonition-title">Save Power <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Reduce battery and network overhead by using batch processing and excluding unnecessary data</p></div><h5 id="whole-house" tabindex="-1">Whole house <a class="header-anchor" href="#whole-house" aria-label="Permalink to &quot;Whole house&quot;">​</a></h5><p>Based on the <a href="https://github.com/jamorham/wixel-xDrip" target="_blank" rel="noreferrer">Parakeet</a> project, multiple <strong>master</strong> devices can create a whole house network.<br> If you use Libre sensors you can also use this feature, see <a href="https://github.com/tzachi-dar/LibreAllHouse" target="_blank" rel="noreferrer">here</a> how to create your whole house network.</p><div class="admonition xdripitem"><p class="admonition-title">Whole House <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Participate in a Whole House Network</p></div><div class="admonition xdripitem"><p class="admonition-title">Libre Whole House <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> This phone will be a collector in a Whole House Network</p></div><h5 id="remote-snoozing" tabindex="-1">Remote snoozing <a class="header-anchor" href="#remote-snoozing" aria-label="Permalink to &quot;Remote snoozing&quot;">​</a></h5><p>Remote snoozing allows the snooze request to propagate along the group. Master or followers can snooze alarms. Use with care.</p><div class="admonition xdripitem"><p class="admonition-title">Send snooze to all <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Snoozes will silence all handsets in group with the accept setting below enabled on them</p></div><div class="admonition xdripitem"><p class="admonition-title">Confirm sending snooze <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Pop up a dialog to confirm sending each remote snooze</p></div><div class="admonition xdripitem"><p class="admonition-title">Accept remote snoozes <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Allow remote handsets to silence alarms on this one</p></div><div class="admonition xdripitem"><p class="admonition-title">WiFi name must match <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Only accept if the remote WiFi network name starts with the same letters as ours and matches very closely</p></div><h5 id="local-broadcast" tabindex="-1">Local Broadcast <a class="header-anchor" href="#local-broadcast" aria-label="Permalink to &quot;Local Broadcast&quot;">​</a></h5><p>Local Broadcast sends or accepts snoozes to/from other (non-xDrip) apps installed on the same handset, separate from remote snoozing between xDrip handsets.</p><div class="admonition xdripitem"><p class="admonition-title">Local Broadcast <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Send snoozes to other apps on this handset</p></div><div class="admonition xdripitem"><p class="admonition-title">Accept Local Broadcast <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Accept snoozes from other apps on this handset</p></div><h5 id="disable-sync" tabindex="-1">Disable sync <a class="header-anchor" href="#disable-sync" aria-label="Permalink to &quot;Disable sync&quot;">​</a></h5><p>Disable Sync completely disables sharing. You might need to restart your phone when you enable it back.</p><p>You can use this option in case of complete Sync failure or when using a phone without Google Play Services.</p><div class="admonition xdripitem"><p class="admonition-title">Disable all Sync features <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Temporary work-around option, completely stops all synchronization. May need reboot after being re-enabled. Use with care!</p></div><h3 id="desert-sync" tabindex="-1">Desert Sync <a class="header-anchor" href="#desert-sync" aria-label="Permalink to &quot;Desert Sync&quot;">​</a></h3><p>Desert Sync allows xDrip sync without internet or phone data coverage.</p><div class="admonition xdripitem"><p class="admonition-title">Desert Sync</p><p><img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xxhdpi/desert_sync.png" style="width:5%;"> Off-grid following</p></div><p>Desert Sync allows you to share data between your xDrip master and followers when internet is not available. This can happen when traveling out of phone coverage or on a local intranet (no internet access).</p><p>Enable desert sync on all devices.</p><div class="admonition xdripitem"><p class="admonition-title">Desert Sync <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Enabled local non-internet sync facilities</p></div><p>If you know the IP address of the master (this is for local intranets) enter it here.<br> You will find the master IP in the phone Android settings - About phone - IP address.</p><div class="admonition xdripitem"><p class="admonition-title">Master IP address</p></div><p>Now display the master settings QR code and scan it on your followers using <a href="./copysettings.html#auto-configure">auto configure</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Show QR Code</p><p>Barcode for followers to scan to auto-configure them</p></div><p>If you want to secure your connection (local intranets and public wifi) you can enable https.</p><div class="admonition xdripitem"><p class="admonition-title">Use HTTPS <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Add another layer of encryption for shared networks, e.g. public WiFi</p></div><p>If you&#39;re without mobile or Wi-Fi data, put the master phone in Wi-Fi hotspot mode and connect the followers through tethering. Maximum distance between devices will be limited. This will also weigh heavily on the master battery; make sure you have a backup power bank available.<br> When using tethering you will need to enable a <a href="./interapp.html#web-service">web service</a> on the master. Make sure the secret is identical on master and followers.</p><p>Look in system status to check everything is connecting correctly.</p><img src="'+i+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',56)])])}const z=n(p,[["render",d]]);export{_ as __pageData,z as default};
